struct OccupationPolicies final: OccupationFiscalPolicyRead {
 CommonStore& common;OccupationFiscalPolicySource source;std::function<Status()> verify_sources;
 explicit OccupationPolicies(CommonStore& c,bool enabled=true):common(c){if(enabled)activate();}
 void activate(){
  auto fact=[&](const StableId& prefix,const StableId& kind,const StableId& domain){auto id=common.next_id(prefix);assert(id.ok&&common.append_fact({id.value,kind,domain}).ok);return id.value;};
  source.occupation_fact_id=fact("military","military_occupation","military");source.registration_fact_id=fact("political_takeover_pending","political_public_responsibilities_pending","politics");
  source.policy={"district","town","city","city.wallet","city.inventory",fact(political_occupation_fiscal_id_prefix,political_occupation_fiscal_fact_kind,"politics"),1,0,1,FiscalTaxMode::normal};source.occupation_rule={"fixture.occupation",1,20,5000};source.occupation_tick=common.tick();source.policy.issued_tick=common.tick();source.policy.effective_from_tick=common.tick()+1;source.integration_until_tick=common.tick()+20;
 }
 Outcome<std::optional<OccupationFiscalPolicySource>> occupation_fiscal_policy_for_due_tick(const StableId& site,Integer due)const override{if(verify_sources){auto valid=verify_sources();if(!valid.ok)return {false,{},valid.error};}if(site!="town"||due<0||due>common.tick()+1)return {false,{},common_failure("InvalidComponentPolicyTick").error};if(source.policy.source_fact_id.empty()||due<source.policy.effective_from_tick)return {true,std::nullopt,{}};auto out=source;out.source_identity=common.state().identity;out.income_basis_points=due<out.integration_until_tick?5000:10000;return {true,out,{}};}
 Outcome<std::optional<OccupationFiscalPolicySource>> occupation_fiscal_policy_for_assessment_source(const StableId& site,Integer due,const StableId& id)const override{auto out=occupation_fiscal_policy_for_due_tick(site,due);if(out.ok&&out.value&&out.value->policy.source_fact_id!=id)return {false,{},common_failure("WrongComponentPolicySource").error};return out;}
};
