// 模拟真实政策读的责任反向全扫：本期新债已写入，但财政时钟尚待本次事务尾提交。
void preclock_responsibility_read(){
 FiscalIncomeFixture f;f.step(1);DynamicStepInput input{1,2,{},{},{}};int pending_reads=0;
 EconomicPublicAccountSelection selected{{Owner::Kind::organization,"city",{}},{"city.wallet"},{"city.inventory"}};
 f.policy.verify_sources=[&](){for(const auto& row:f.income.assessments.rows()){
  EconomicResponsibilityRef ref{EconomicResponsibilityKind::fiscal_assessment,row.first,{}};
  if(f.income.last_step_tick<input.to_tick){++pending_reads;auto cold=read_occupation_fiscal_responsibility_source(f.common,f.economy,f.taxes,f.income,selected,ref);assert(!cold.ok);DynamicStepInput wrong{1,3,{},{},{}};assert(!read_occupation_fiscal_responsibility_source(f.common,f.economy,f.taxes,f.income,selected,ref,&wrong).ok);}
  auto source=read_occupation_fiscal_responsibility_source(f.common,f.economy,f.taxes,f.income,selected,ref,&input);if(!source.ok)return Status{false,{},source.error};
 }return common_success();};
 assert(step_local_economy(f.common,f.economy,f.catalog,f.organizations_read,f.activities,input).ok);
 assert(step_fiscal_settlement(f.common,f.economy,f.catalog,f.organizations_read,f.old_policy,f.taxes,f.legacy,input).ok);
 auto result=step_occupation_fiscal_settlement(f.common,f.income,f.context(&input),input);if(!result.ok)std::cerr<<"preclock responsibility: "<<result.error.original.code<<"\n";assert(result.ok&&pending_reads>0);
 assert(f.common.tick()==1&&f.income.last_step_tick==2&&f.income.assessments.size()==1&&f.income.payments.size()==1);
 f.policy.verify_sources={};f.common.state().identity.tick=2;assert(validate_occupation_fiscal_settlement(f.context(),f.income).ok);
}
